from rendu import Point
p=Point(10)
p.h('Commencer par les menaces qui changent immédiatement le lieu de soins')
p.p('Si les constantes sont anormales, si les urines deviennent très foncées ou absentes, ou si une complication métabolique accompagne la douleur → évaluer immédiatement une rhabdomyolyse et son risque rénal. Le chiffre de CK ne remplace pas cette appréciation.', 'e13')
p.p('Si la douleur est disproportionnée après une atteinte du membre et s’accentue à la mobilisation passive → rechercher un syndrome compartimental aigu. Une fois ce diagnostic établi, organiser la décompression immédiate, sans laisser la qualification de « contusion » retarder la conduite.', ['p83-boast-loges-0','p83-boast-loges-3'])
p.p('Si des douleurs de ceinture s’accompagnent de signes crâniens ou visuels évocateurs d’artérite → adresser immédiatement ; en cas de forte suspicion, commencer les glucocorticoïdes sans attendre la confirmation. L’échographie ou la biopsie organise ensuite la preuve diagnostique.', ['p83-eular26-orientation','p83-eular26-urgence','p83-eular23-imagerie-urgente'])
p.p('Si la faiblesse s’accompagne de dysphagie importante, d’atteinte pulmonaire ou de myocardite → prendre la filière urgente spécialisée de myopathie inflammatoire. Une force encore relativement conservée dans les membres ne suffit pas à exclure une atteinte de déglutition dangereuse.', ['dx10-pnds-severite','dx10-bsr-xi'])
p.p('Si le contexte est respiratoire chez l’adulte → confronter l’état général aux alarmes SSI : pression systolique inférieure à90mmHg, fréquence respiratoire d’au moins30/min, saturation inférieure à92%, hémoptysie ou stridor, notamment. Une de ces situations conduit à envisager l’hospitalisation.', 'flu-ssi-alarmes')
p.h('Chez le patient stable : relier territoire, temps et déclencheur')
p.tableau(['Si le tableau est…','Alors rechercher…','Décision qui en découle'],[
 [('Une douleur localisée reproduite par la pression d’une bande tendue.', 'p83-myofascial-fibro'),('Le point de sensibilité maximale, la contraction locale et la propagation de la douleur.', 'p83-myofascial-fibro'),('Retenir une démarche clinique myofasciale et une prise en charge multimodale si les constatations concordent.', 'p83-myofascial-fibro')],
 [('Une douleur retardée après charge inhabituelle, sans alarme systémique.', ['doms-definition','e13']),('La chronologie des DOMS et une évolution compatible avec l’adaptation musculaire.', ['doms-definition','doms-prevention']),('Adapter la charge et observer l’évolution ; une discordance ou une aggravation conduit à reprendre l’examen.', ['doms-prevention','e13'])],
 [('Une douleur immédiatement liée à un coup direct.', 'p83-doms-contusion-clinique'),('La localisation, l’hématome, la mobilité et les réponses à l’étirement/contraction.', 'rms-clinique'),('Prendre la branche traumatique et rester attentif à la complication de loges.', ['rms-clinique','p83-boast-loges-0'])],
 [('Une douleur généralisée persistante avec fatigue et sommeil non réparateur.', 'p83-myofascial-fibro'),('La répartition des sites et régions, le WPI, le SSS et la durée des symptômes.', 'f83-rcp-annexe2016'),('Appliquer les critères cliniques tout en évaluant les anomalies ou maladies associées.', ['f83-rcp-criteres','f83-rcp-coexistence'])],
 [('Une faiblesse proximale progressive sous statine.', 'p83-statine-imnm'),('Les CK, la dysphagie et, si le phénotype l’indique, les anti-HMGCR.', 'p83-statine-imnm'),('Suspendre selon la notice et organiser l’avis spécialisé si la faiblesse persiste ou évoque une forme immunomédiée.', ['aips-sortis-surveillance','p83-statine-imnm'])],
 [('Une myalgie avec contexte évocateur d’hypothyroïdie.', 'p83-hypothyroidie'),('TSH, hormones libres et retentissement neuromusculaire.', 'p83-hypothyroidie'),('Retenir une stratégie étiologique endocrinienne plutôt que poursuivre uniquement l’antalgie.', 'p83-hypothyroidie')],
 [('Une douleur inflammatoire des ceintures sans signe crânien urgent.', ['p83-pmr','p83-eular26-signes-urgence']),('Les imitateurs et les éléments de confirmation avant une corticothérapie diagnostique.', 'p83-eular26-diagnostic'),('Adresser pour une évaluation experte ; éviter l’essai de glucocorticoïdes comme test.', ['p83-eular26-orientation','p83-eular26-pas-test-gc'])],
 [('Une faiblesse proximale associée à des lésions cutanées évocatrices.', ['dx10-pnds-examen','dx10-cedef-gottron']),('Le bilan musculaire et les atteintes de déglutition, cardiaques et pulmonaires.', ['dx10-pnds-examen','p83-myopathies-gravite']),('Orienter vers le centre spécialisé, avec urgence adaptée au retentissement réel.', 'dx10-pnds-severite')]
])
p.fenetre('Que faire lorsque les résultats ne concordent pas ?',[
 ('Si une CK normale contraste avec un déficit objectif → poursuivre la démarche clinique appropriée, car certaines myosites et causes thyroïdiennes n’élèvent pas nécessairement cette enzyme.', ['pa83-biologie','p83-hypothyroidie']),
 ('Si l’IRM montre une anomalie non spécifique → la confronter à la distribution clinique, à la biologie et éventuellement à la biopsie. Une lésion visible ne porte pas automatiquement le nom de la maladie suspectée.', 'pa83-imagerie'),
 ('Si l’amélioration après arrêt de statine ne survient pas et que le phénotype est progressif → reconsidérer une myopathie nécrosante immunomédiée. L’arrêt isolé ne suffit généralement pas pour cette forme.', 'p83-statine-imnm'),
 ('Si une nouvelle anomalie objective apparaît chez une personne fibromyalgique → l’évaluer pour elle-même, puisque les diagnostics peuvent coexister.', 'f83-rcp-coexistence')
])
p.sauver()
